package ubuntusure.dao;
import ubuntusure.config.Database; import java.sql.*; import java.util.*;
public class ReportDao {
 public List<String[]> policyRows()throws SQLException{List<String[]> rows=new ArrayList<>();String q="SELECT p.policy_number,c.first_name,c.surname,p.product_type,p.start_date,p.end_date,p.coverage_amount,p.annual_premium,p.status FROM policies p JOIN customers c ON c.customer_id=p.customer_id ORDER BY p.created_at DESC";try(Connection c=Database.getConnection();PreparedStatement s=c.prepareStatement(q);ResultSet r=s.executeQuery()){ResultSetMetaData m=r.getMetaData();String[] h=new String[m.getColumnCount()];for(int i=1;i<=h.length;i++)h[i-1]=m.getColumnLabel(i);rows.add(h);while(r.next()){String[] row=new String[h.length];for(int i=1;i<=h.length;i++)row[i-1]=r.getString(i);rows.add(row);}}return rows;}
 public List<String[]> claimRows()throws SQLException{List<String[]> rows=new ArrayList<>();String q="SELECT cl.claim_number,p.policy_number,c.first_name,c.surname,cl.date_submitted,cl.claim_amount,cl.status,cl.approved_amount FROM claims cl JOIN policies p ON p.policy_id=cl.policy_id JOIN customers c ON c.customer_id=cl.customer_id ORDER BY cl.date_submitted DESC";try(Connection c=Database.getConnection();PreparedStatement s=c.prepareStatement(q);ResultSet r=s.executeQuery()){ResultSetMetaData m=r.getMetaData();String[] h=new String[m.getColumnCount()];for(int i=1;i<=h.length;i++)h[i-1]=m.getColumnLabel(i);rows.add(h);while(r.next()){String[] row=new String[h.length];for(int i=1;i<=h.length;i++)row[i-1]=r.getString(i);rows.add(row);}}return rows;}
 public List<String[]> customerRows()throws SQLException{List<String[]> rows=new ArrayList<>();String q="SELECT customer_id,first_name,surname,national_id,phone,email FROM customers ORDER BY customer_id";try(Connection c=Database.getConnection();PreparedStatement s=c.prepareStatement(q);ResultSet r=s.executeQuery()){ResultSetMetaData m=r.getMetaData();String[] h=new String[m.getColumnCount()];for(int i=1;i<=h.length;i++)h[i-1]=m.getColumnLabel(i);rows.add(h);while(r.next()){String[] row=new String[h.length];for(int i=1;i<=h.length;i++)row[i-1]=r.getString(i);rows.add(row);}}return rows;}
}
